{
  "paragraphs": [
    {
      "component_id": "concern_001",
      "text": "A product that arrives with a cracked charging socket is considered defective because it does not provide the safety a consumer rightfully expects, taking its presentation and the hazards reasonably expected of it into account. The manufacturer, producer or importer is liable for redress regardless of fault, but they can escape liability only if they prove they never placed the product on the market, that the product had no defect when placed, or that the consumer or a third party caused the damage. If the retailer (as a supplier) does not fix the imperfection within thirty days, you may choose either a replacement of a perfect unit, a full refund with monetary updating, or a proportionate price reduction, provided the agreed correction period is not less than seven days or more than one hundred eighty days.",
      "evidence": [
        { "quote_id": "concern_001.s1.q2" },
        { "quote_id": "concern_001.s1.q7" },
        { "quote_id": "concern_001.s2.q2" }
      ]
    },
    {
      "component_id": "concern_002",
      "text": "Under the consumer act, any durable product sold in a retail transaction that is unfit for its intended use—such as a lamp with a cracked socket—triggers the supplier’s liability for product imperfections, and the consumer may demand a replacement, a refund with monetary updating, or a proportional price reduction if the defect is not remedied within thirty days, subject to a correction period of at least seven days and at most one hundred eighty days.",
      "evidence": [
        { "quote_id": "concern_002.s1.q2" },
        { "quote_id": "concern_002.s2.q2" }
      ]
